contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 1000000000000000000); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Call AdjustBetAmounts and then assert the public getter matches the input amount
    function testAdjustBetLimit(uint256 amount) public {
        // call the state-changing function on C
        c.AdjustBetAmounts(amount); if (__ESBMC_reverted()) return;

        // check the public getter reflects exactly the passed amount
        assert(c.currentBetLimit() == amount);
    }

    // allow receiving ETH just in case
    receive() external payable {}
}

