pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 1000000000000000000);
    }

    function _testAdjustBetLimit(uint256 amount) internal {
        try c.AdjustBetAmounts(amount) {} catch { return; }
        assertTrue(c.currentBetLimit() == amount);
    }

    function testFuzz_testAdjustBetLimit(uint256 amount) public {
        _testAdjustBetLimit(amount);
    }

    receive() external payable {}
}
